"""One message through the whole graph on mock providers (generated by adk_v2/6.0.0)."""

from retail_kyc_onboarding._engine.datatypes import Principal
from retail_kyc_onboarding._engine.engine.host import RunHost
from retail_kyc_onboarding._engine.testing.trajectory import check_trajectory

PRINCIPAL = Principal("test-user", roles=("offline-approver",))


async def test_a_run_follows_the_graph(offline_engine):
    """A run on mock providers does not fail and its trace follows the graph."""
    result = await RunHost(offline_engine).start(message="hello", principal=PRINCIPAL)
    assert result.status != "error", result.error
    problems = check_trajectory(offline_engine.factories.telemetry.sink.records, offline_engine.unit.graph)
    assert not problems, problems


async def test_the_same_input_takes_the_same_steps(offline_engine):
    """Two runs of the same message visit the same nodes in the same order."""

    async def steps() -> list[str]:
        offline_engine.factories.telemetry.sink.records.clear()
        await RunHost(offline_engine).start(message="hello", principal=PRINCIPAL)
        return [r["node"] for r in offline_engine.factories.telemetry.sink.records if r.get("event") == "step.start"]

    first = await steps()
    assert first and first == await steps()
